+template <typename T>
+SGL_DEVICE const T* cp_input_relative(
+    const T* source,
+    int64_t relative,
+    int64_t width,
+    int64_t input_row,
+    int64_t rows_per_rank = 0,
+    int64_t cp_size = 8) {
